import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"卷阿","description":"","frontmatter":{"title":"卷阿","date":"2026-11-09T00:00:00.000Z","seq":18,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/卷阿.md","filePath":"blogs/诗经·大雅/卷阿.md"}'),o={name:"blogs/诗经·大雅/卷阿.md"};function c(l,a,n,r,m,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="卷阿" tabindex="-1">卷阿 <a class="header-anchor" href="#卷阿" aria-label="Permalink to &quot;卷阿&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　生民之什</p><div class="poem"><p class="poem-stanza">有卷者阿，飘风自南。岂弟君子，来游来歌，以矢其音。</p><p class="poem-stanza">伴奂尔游矣，优游尔休矣。岂弟君子，俾尔弥尔性，似先公酋矣。</p><p class="poem-stanza">尔土宇昄章，亦孔之厚矣。岂弟君子，俾尔弥尔性，百神尔主矣。</p><p class="poem-stanza">尔受命长矣，茀禄尔康矣。岂弟君子，俾尔弥尔性，纯嘏尔常矣。</p><p class="poem-stanza">有冯有翼，有孝有德，以引以翼。岂弟君子，四方为则。</p><p class="poem-stanza">颙颙卬卬，如圭如璋，令闻令望。岂弟君子，四方为纲。</p><p class="poem-stanza">凤凰于飞，翙翙其羽，亦集爰止。蔼蔼王多吉士，维君子使，媚于天子。</p><p class="poem-stanza">凤凰于飞，翙翙其羽，亦傅于天。蔼蔼王多吉人，维君子命，媚于庶人。</p><p class="poem-stanza">凤凰鸣矣，于彼高冈。梧桐生矣，于彼朝阳。菶菶萋萋，雍雍喈喈。</p><p class="poem-stanza">君子之车，既庶且多。君子之马，既闲且驰。矢诗不多，维以遂歌。</p></div>',3)])])}const u=s(o,[["render",c]]);export{d as __pageData,u as default};
